60	 */
61	
62	@RestController
63	@CrossOrigin(exposedHeaders = "errors, content-type")
64	@RequestMapping("/api")
65	public class OwnerRestControllerV1 implements OwnersApi {
66	
67	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
68	
69	    /**
70	     * Fixed public-holiday calendar. A registration date that lands on one of these dates is rolled
71	     * forward to the next non-holiday business day, in the same way weekends are.
72	     */
73	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
74	        LocalDate.of(2026, 1, 1),
75	        LocalDate.of(2026, 1, 26),
76	        LocalDate.of(2026, 4, 25),
77	        LocalDate.of(2026, 12, 25),
78	        LocalDate.of(2026, 12, 28));
79	
80	    private final ClinicService clinicService;
81	
82	    private final OwnerMapper ownerMapper;
83	
84	    private final PetMapper petMapper;
85	
86	    private final VisitMapper visitMapper;
87	
88	    private final AddressNormalizer addressNormalizer;
89	
90	    public OwnerRestControllerV1(ClinicService clinicService,
91	                                 OwnerMapper ownerMapper,
92	                                 PetMapper petMapper,
93	                                 VisitMapper visitMapper,
94	                                 AddressNormalizer addressNormalizer) {
95	        this.clinicService = clinicService;
96	        this.ownerMapper = ownerMapper;
97	        this.petMapper = petMapper;
98	        this.visitMapper = visitMapper;
99	        this.addressNormalizer = addressNormalizer;
100	    }
101	
102	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
103	    @Override
104	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
105	        Collection<Owner> owners;
106	        if (lastName != null) {
107	            owners = this.clinicService.findOwnerByLastName(lastName);
108	        } else {
109	            owners = this.clinicService.findAllOwners();
110	        }
111	        if (owners.isEmpty()) {
112	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
113	        }
114	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
115	    }
116	
117	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
118	    @Override
119	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
120	        Owner owner = this.clinicService.findOwnerById(ownerId);
121	        if (owner == null) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
130	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
131	
132	        HttpStatus invalid = normalizeAndValidate(owner);
133	        if (invalid != null) {
134	            return new ResponseEntity<>(invalid);
135	        }
136	        if (isDailyLimitReached(owner.getRegistrationDate())) {
137	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
138	        }
139	
140	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
141	        assignHousehold(owner);
142	
143	        HttpStatus conflict = checkForConflicts(owner, sharesHousehold);
144	        if (conflict != null) {
145	            return new ResponseEntity<>(conflict);
146	        }
147	
148	        assignDerivedAttributes(owner, sharesHousehold);
149	        this.clinicService.saveOwner(owner);
150	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
151	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
152	            owner.getMembershipLevel(), owner.getMembershipNumber());
153	        return created(owner);
154	    }
155	
156	    /**
157	     * Bring a freshly mapped owner into its canonical, valid form, or report the reason it must be
158	     * rejected. The owner's {@link #normalizeAddress(Owner) address is normalized} (a missing address
159	     * is rejected), its telephone is converted to E.164 (an unconvertible number is rejected), its
160	     * postcode is checked against its city's region, a registration date in the future is rejected,
161	     * and the effective registration date (the supplied one, or today when none was given) is rolled
162	     * onto a business day and stored back on the owner. Returns {@code null} once the owner is valid
163	     * and normalized, or the {@link HttpStatus} the create must fail with ({@code 400 Bad Request})
164	     * otherwise.
165	     */
166	    private HttpStatus normalizeAndValidate(Owner owner) {
167	        if (!normalizeAddress(owner)) {
168	            return HttpStatus.BAD_REQUEST;
169	        }
170	        String telephone = toE164(owner.getTelephone());
171	        if (telephone == null) {
172	            return HttpStatus.BAD_REQUEST;
173	        }
174	        owner.setTelephone(telephone);
175	        if (isDisposableEmail(owner.getEmail())) {
176	            return HttpStatus.BAD_REQUEST;
177	        }
178	        if (!owner.isPostcodeValid()) {
179	            return HttpStatus.BAD_REQUEST;
180	        }
181	        if (owner.getRegistrationDate() != null
182	            && owner.getRegistrationDate().isAfter(LocalDate.now())) {
183	            return HttpStatus.BAD_REQUEST;
184	        }
185	        LocalDate effectiveDate = owner.getRegistrationDate() != null
186	            ? owner.getRegistrationDate() : LocalDate.now();
187	        owner.setRegistrationDate(toBusinessDay(effectiveDate));
188	        return null;
189	    }
190	
191	    /**
192	     * Normalize the owner's supplied address into its canonical stored form and report whether an
193	     * address was supplied at all. The owner may supply its address either as the structured
194	     * {@code addressLine1}/{@code addressLine2} fields or as the flat {@code address} field, which is
195	     * kept for backward compatibility; the structured form is preferred whenever a non-blank
196	     * {@code addressLine1} is present. Each supplied field is run through the {@link AddressNormalizer}
197	     * (trimmed, whitespace-collapsed, upper-cased, common street-type abbreviations expanded). When the
198	     * structured form is used, the normalized {@code addressLine1} and {@code addressLine2} are stored
199	     * back and the composed {@link Owner#getAddress() address} becomes the normalized
200	     * {@code addressLine1} with a single space and the normalized {@code addressLine2} appended when an
201	     * {@code addressLine2} is present; when the flat form is used, the normalized flat address is
202	     * stored and no structured lines are kept. Returns {@code true} once a non-blank address has been
203	     * normalized and stored, or {@code false} when neither form supplied an address, in which case the
204	     * create must be rejected with {@code 400 Bad Request}.
205	     */
206	    private boolean normalizeAddress(Owner owner) {
207	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
208	        if (!line1.isEmpty()) {
209	            String line2 = addressNormalizer.normalize(owner.getAddressLine2());
210	            owner.setAddressLine1(line1);
211	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
212	            owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
213	            return true;
214	        }
215	        String address = addressNormalizer.normalize(owner.getAddress());
216	        if (address.isEmpty()) {
217	            return false;
218	        }
219	        owner.setAddressLine1(null);
220	        owner.setAddressLine2(null);
221	        owner.setAddress(address);
222	        return true;
223	    }
224	
225	    /**
226	     * The set of disposable (throwaway) email domains that an owner's email may not use. An owner
227	     * whose email is hosted on one of these domains is rejected with {@code 400 Bad Request}.
228	     */
229	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
230	        "mailinator.com", "tempmail.com", "guerrillamail.com");
231	
232	    /**
233	     * Whether the given email is hosted on a {@linkplain #DISPOSABLE_EMAIL_DOMAINS disposable}
234	     * domain. The email is optional, so a {@code null} or empty email is not disposable; otherwise
235	     * the domain (the part after the last {@code '@'}, compared case-insensitively) is matched
236	     * against the blocklist.
237	     */
238	    private boolean isDisposableEmail(String email) {
239	        if (email == null || email.isEmpty()) {
240	            return false;
241	        }
242	        int at = email.lastIndexOf('@');
243	        if (at < 0) {
244	            return false;
245	        }
246	        String domain = email.substring(at + 1).toLowerCase();
247	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
248	    }
249	
250	    /**
251	     * Assign the owner its household link. The {@link #householdId(Owner) householdId} is computed
252	     * deterministically from the owner's lastName and postcode, so every owner sharing that
253	     * lastName and postcode is assigned the same value automatically, independent of whether the
254	     * owner declares it shares a household. The link is assigned before the
255	     * {@link #checkForConflicts(Owner, boolean) conflict checks} because it is part of the owner's
256	     * {@link Owner#getIdentityKey() identity} and feeds its {@link #householdSize(String) household
257	     * size}.
258	     */
259	    private void assignHousehold(Owner owner) {
260	        owner.setHouseholdId(householdId(owner));
261	    }
262	
263	    /**
264	     * Whether the owner clashes with an owner that already exists, and the {@link HttpStatus} the
265	     * create must fail with when it does. An owner is rejected with {@code 409 Conflict} when it
266	     * {@link #isHouseholdDuplicate(Owner) duplicates an existing household} or when its
267	     * {@link #isCityAtCapacity(String) city is already at capacity}. Declaring {@code
268	     * sharesHousehold} bypasses only the household-duplicate block (the owner is then created as a
269	     * declared household member); it does not lift the city-capacity limit. Returns {@code null}
270	     * when the owner clashes with nothing and may be created.
271	     */
272	    private HttpStatus checkForConflicts(Owner owner, boolean sharesHousehold) {
273	        if (!sharesHousehold && isHouseholdDuplicate(owner)) {
274	            return HttpStatus.CONFLICT;
275	        }
276	        if (isCityAtCapacity(owner.getCity())) {
277	            return HttpStatus.CONFLICT;
278	        }
279	        return null;
280	    }
281	
282	    /**
283	     * Build the {@code 201 Created} response for a persisted owner: its {@link OwnerDto} body and a
284	     * {@code Location} header pointing at {@code /api/owners/{id}}.
285	     */
286	    private ResponseEntity<OwnerDto> created(Owner owner) {
287	        HttpHeaders headers = new HttpHeaders();
288	        headers.setLocation(UriComponentsBuilder.newInstance()
289	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
290	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), headers, HttpStatus.CREATED);
291	    }
292	
293	    /**
294	     * Assign the attributes that are derived once, at creation time, and stored on the owner: its
295	     * {@link #customerCode(Owner) customerCode}, {@link #namesakeCount(String, String) namesakeCount},
296	     * {@link #isBulkSignup(LocalDate) bulk-signup warning} and {@link #householdSize(String)
297	     * householdSize}. Each is computed from the owner's own fields together with the owners already
298	     * present, so this runs after the owner has been validated and has passed the duplicate and
299	     * capacity checks, and immediately before it is persisted.
300	     */
301	    private void assignDerivedAttributes(Owner owner, boolean sharesHousehold) {
302	        owner.setCustomerCode(customerCode(owner));
303	        owner.setNamesakeCount(namesakeCount(owner.getFirstName(), owner.getLastName()));
304	        owner.setBulkSignupWarning(isBulkSignup(owner.getRegistrationDate()));
305	        owner.setHouseholdSize(householdSize(owner.getHouseholdId()));
306	        assignPossibleDuplicate(owner, sharesHousehold);
307	    }
308	
309	    /**
310	     * Flag a newly created owner as a possible (soft) duplicate. An owner that declares it shares a
311	     * household ({@code sharesHousehold}) is a declared household member, not a suspected duplicate,
312	     * so it is never flagged. Otherwise, because this runs after the hard
313	     * {@link #isHouseholdDuplicate(Owner) household-duplicate} check, the owner is not a household
314	     * match; it is flagged only when it is a soft match of an existing owner as determined by
315	     * {@link #findSoftDuplicate(Owner)}. When such an owner exists the new owner is flagged with
316	     * {@code possibleDuplicate = true} and {@code possibleDuplicateOf} set to that owner's id;
317	     * otherwise {@code possibleDuplicate = false} and no matching id is recorded.
318	     */
319	    private void assignPossibleDuplicate(Owner owner, boolean sharesHousehold) {
320	        Owner match = sharesHousehold ? null : findSoftDuplicate(owner);
321	        owner.setPossibleDuplicate(match != null);
322	        owner.setPossibleDuplicateOf(match == null ? null : match.getId());
323	    }
324	
325	    /**
326	     * The owners a newly created owner is checked against by the duplicate and identity rules:
327	     * the {@link #isHouseholdDuplicate(Owner) household-duplicate} and {@link #findSoftDuplicate(Owner)
328	     * soft-duplicate} checks, the {@link #customerCode(Owner) customerCode} de-duplication and the
329	     * {@link #namesakeCount(String, String) namesake} count. This is the single place that scope is
330	     * defined, so every one of those rules considers exactly the same set of owners; it spans every
331	     * owner the clinic holds except those flagged {@linkplain Owner#isDeleted() deleted}, which a
332	     * soft delete retains but excludes from duplicate and identity detection.
333	     */
334	    private Collection<Owner> activeOwners() {
335	        return this.clinicService.findAllOwners().stream()
336	            .filter(owner -> !owner.isDeleted())
337	            .collect(Collectors.toList());
338	    }
339	
340	    /**
341	     * The existing owner this owner softly duplicates, or {@code null} when there is none. A soft
342	     * match is an existing owner that shares this owner's lastName (compared case-insensitively,
343	     * with collapsed whitespace) and its postcode but carries a different telephone; the earliest
344	     * such owner (by id) is returned. A postcode is required for a soft match, so an owner without a
345	     * postcode never matches.
346	     */
347	    private Owner findSoftDuplicate(Owner owner) {
348	        if (owner.getPostcode() == null) {
349	            return null;
350	        }
351	        String candidateLastName = normalizeName(owner.getLastName());
352	        return activeOwners().stream()
353	            .filter(existing -> owner.getPostcode().equals(existing.getPostcode()))
354	            .filter(existing -> normalizeName(existing.getLastName()).equals(candidateLastName))
355	            .filter(existing -> !owner.getTelephone().equals(existing.getTelephone()))
356	            .min(Comparator.comparingInt(Owner::getId))
357	            .orElse(null);
358	    }
359	
360	    /**
361	     * Build the customer code for a newly created owner, formatted {@code '<REGION>-<HASH8>'}
362	     * where REGION is the region derived from the owner's postcode (or {@link Owner#UNKNOWN_REGION}
363	     * when the postcode is absent or maps to no known region) and HASH8 is the first 8 upper-case
364	     * hex characters of the SHA-256 of the normalized (E.164) telephone concatenated with the
365	     * lastName (e.g. {@code 'NSW-3C1A9F2B'}). This is the single source of the owner's identity:
366	     * every value built from the customer code (the membership number and its check digit) and the
367	     * owner's locality are derived from it.
368	     *
369	     * <p>When the computed code collides with an existing owner's {@code customerCode}, a
370	     * {@code '-<n>'} suffix is appended with the smallest {@code n} of 2 or more that makes the code
371	     * unique, and the de-duplicated code is returned.
372	     */
373	    private String customerCode(Owner owner) {
374	        String region = owner.getRegion() != null ? owner.getRegion() : Owner.UNKNOWN_REGION;
375	        String hash8 = shaHexUpper(owner.getTelephone() + owner.getLastName()).substring(0, 8);
376	        String base = region + "-" + hash8;
377	
378	        Set<String> existingCodes = activeOwners().stream()
379	            .map(Owner::getCustomerCode)
380	            .filter(Objects::nonNull)
381	            .collect(Collectors.toSet());
382	
383	        if (!existingCodes.contains(base)) {
384	            return base;
385	        }
386	        int n = 2;
387	        while (existingCodes.contains(base + "-" + n)) {
388	            n++;
389	        }
390	        return base + "-" + n;
391	    }
392	
393	    /**
394	     * Whether the per-day owner creation limit has been reached for the given business day, i.e.
395	     * 100 or more owners already carry that {@code registrationDate}. The day is the adjusted
396	     * (business-day) registration date of the owner being created, so owners are counted per
397	     * business day. When true, a new owner must be rejected with {@code 429 Too Many Requests}.
398	     */
399	    private boolean isDailyLimitReached(LocalDate day) {
400	        long count = this.clinicService.findAllOwners().stream()
401	            .filter(existing -> day.equals(existing.getRegistrationDate()))
402	            .count();
403	        return count >= 100;
404	    }
405	
406	    /**
407	     * Whether creating this owner pushes the day's total past the bulk-signup threshold, i.e.
408	     * more than 80 owners have already been created for the given business day. Counts the owners
409	     * already carrying that {@code registrationDate} (the same accumulation as the daily-limit
410	     * rule); when that count exceeds 80 the newly created owner is flagged with a bulk-signup
411	     * warning.
412	     */
413	    private boolean isBulkSignup(LocalDate day) {
414	        long count = this.clinicService.findAllOwners().stream()
415	            .filter(existing -> day.equals(existing.getRegistrationDate()))
416	            .count();
417	        return count > 80;
418	    }
419	
420	    /**
421	     * Roll a registration date forward onto a business day: when it falls on a Saturday, Sunday or a
422	     * listed public holiday, advance it to the next non-holiday weekday; an ordinary weekday is
423	     * returned unchanged.
424	     */
425	    private LocalDate toBusinessDay(LocalDate date) {
426	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
427	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
428	            || PUBLIC_HOLIDAYS.contains(date)) {
429	            date = date.plusDays(1);
430	        }
431	        return date;
432	    }
433	
434	    /**
435	     * Whether the given city has reached its owner capacity, i.e. it already contains 50 or
436	     * more owners. Cities are compared case-insensitively.
437	     */
438	    private boolean isCityAtCapacity(String city) {
439	        long count = this.clinicService.findAllOwners().stream()
440	            .filter(existing -> existing.getCity() != null && existing.getCity().equalsIgnoreCase(city))
441	            .count();
442	        return count >= 50;
443	    }
444	
445	    /**
446	     * The number of existing owners that already share the given firstName and lastName,
447	     * compared case-insensitively (and with surrounding whitespace trimmed and internal
448	     * whitespace runs collapsed). Counted over the owners present before this create.
449	     */
450	    private int namesakeCount(String firstName, String lastName) {
451	        String candidateFirstName = normalizeName(firstName);
452	        String candidateLastName = normalizeName(lastName);
453	        return (int) activeOwners().stream()
454	            .filter(existing -> normalizeName(existing.getFirstName()).equals(candidateFirstName)
455	                && normalizeName(existing.getLastName()).equals(candidateLastName))
456	            .count();
457	    }
458	
459	    /**
460	     * The number of members in this owner's household after this create: the count of existing
461	     * owners already carrying the same non-null {@code householdId} plus one for the owner being
462	     * created. An owner with no household ({@code householdId == null}) is a household of one.
463	     * Owners sharing a household are matched by their assigned {@code householdId}, so the count
464	     * does not depend on the order in which household members were created.
465	     */
466	    private int householdSize(String householdId) {
467	        if (householdId == null) {
468	            return 1;
469	        }
470	        long existing = this.clinicService.findAllOwners().stream()
471	            .filter(other -> householdId.equals(other.getHouseholdId()))
472	            .count();
473	        return (int) existing + 1;
474	    }
475	
476	    /**
477	     * Convert a raw telephone input to its E.164 representation, or {@code null} if it
478	     * cannot form a valid E.164 number.
479	     *
480	     * <p>A leading '+' and country code are kept when present; otherwise country code
481	     * '+61' is assumed and a single leading '0' is dropped from the national digits.
482	     * Spaces, dashes and brackets (indeed any non-digit) are stripped. The result must
483	     * carry 8 to 15 digits after the '+', and — for a recognised country calling code —
484	     * exactly the national-digit count that code requires (see
485	     * {@link Owner#hasValidNationalLength}); otherwise it is rejected as invalid.
486	     */
487	    private String toE164(String telephone) {
488	        if (telephone == null) {
489	            return null;
490	        }
491	        boolean hasCountryCode = telephone.trim().startsWith("+");
492	        String digits = telephone.replaceAll("\\D", "");
493	        String e164;
494	        if (hasCountryCode) {
495	            e164 = digits;
496	        } else {
497	            if (digits.startsWith("0")) {
498	                digits = digits.substring(1);
499	            }
500	            e164 = "61" + digits;
501	        }
502	        if (e164.length() < 8 || e164.length() > 15) {
503	            return null;
504	        }
505	        if (!Owner.hasValidNationalLength(e164)) {
506	            return null;
507	        }
508	        return "+" + e164;
509	    }
510	
511	    /**
512	     * Whether the candidate owner belongs to a household that already exists, and so must be
513	     * rejected with {@code 409 Conflict} unless it declares {@code sharesHousehold}. The household
514	     * is keyed by the deterministic {@link #householdId(Owner) householdId} (derived from lastName
515	     * and postcode), so any existing owner carrying the same householdId means this owner is a
516	     * second member of an already-registered household. Two owners sharing a lastName and postcode
517	     * are therefore the same household: the second is a household duplicate.
518	     */
519	    private boolean isHouseholdDuplicate(Owner owner) {
520	        String householdId = owner.getHouseholdId();
521	        if (householdId == null) {
522	            return false;
523	        }
524	        return activeOwners().stream()
525	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
526	    }
527	
528	    /**
529	     * Normalize an owner's name for household comparison: trim, collapse internal whitespace runs
530	     * to a single space and lower-case. A null value normalizes to the empty string.
531	     */
532	    private String normalizeName(String value) {
533	        if (value == null) {
534	            return "";
535	        }
536	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
537	    }
538	
539	    /**
540	     * A stable shared identifier for the household an owner belongs to, derived deterministically
541	     * from its lastName and postcode. The lastName is normalized (case-insensitive,
542	     * whitespace-collapsed) before hashing, so every owner sharing the same lastName and postcode is
543	     * assigned the same value regardless of the order in which they are created. Formatted as the
544	     * first 12 upper-case hex characters of the SHA-256 of {@code '<normalizedLastName>|<postcode>'}
545	     * (an absent postcode contributes the empty string).
546	     */
547	    private String householdId(Owner owner) {
548	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
549	        String key = normalizeName(owner.getLastName()) + "|" + postcode;
550	        return shaHexUpper(key).substring(0, 12);
551	    }
552	
553	    /**
554	     * The SHA-256 digest of {@code input}'s UTF-8 bytes, rendered as an upper-case hexadecimal
555	     * string (two hex characters per digest byte, so 64 characters in all). This is the single
556	     * place the hashing-and-hex-encoding is performed; callers that need a shorter opaque token
557	     * take a prefix of the result (e.g. {@link #householdId} keeps the first 12 characters and
558	     * {@link #customerCode} keeps the first 8).
559	     */
560	    private String shaHexUpper(String input) {
561	        try {
562	            byte[] digest = MessageDigest.getInstance("SHA-256")
563	                .digest(input.getBytes(StandardCharsets.UTF_8));
564	            StringBuilder sb = new StringBuilder(digest.length * 2);
565	            for (byte b : digest) {
566	                sb.append(String.format("%02x", b));
567	            }
568	            return sb.toString().toUpperCase();
569	        }
570	        catch (NoSuchAlgorithmException e) {
571	            throw new IllegalStateException("SHA-256 not available", e);
572	        }
573	    }
574	
575	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
576	    @Override
577	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
578	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
579	        if (currentOwner == null) {
580	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
581	        }
582	        currentOwner.setAddress(ownerFieldsDto.getAddress());
583	        currentOwner.setCity(ownerFieldsDto.getCity());
584	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
585	        currentOwner.setLastName(ownerFieldsDto.getLastName());
586	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
587	        this.clinicService.saveOwner(currentOwner);
588	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
589	    }
590	
591	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
592	    @Transactional
593	    @Override
594	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
595	        Owner owner = this.clinicService.findOwnerById(ownerId);
596	        if (owner == null) {
597	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
598	        }
599	        this.clinicService.deleteOwner(owner);
600	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
601	    }
602	
603	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
604	    @Override
605	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
606	        Owner owner = this.clinicService.findOwnerById(ownerId);
607	        if (owner == null) {
608	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
609	        }
610	        HttpHeaders headers = new HttpHeaders();
611	        Pet pet = petMapper.toPet(petFieldsDto);
612	        owner.setId(ownerId);
613	        pet.setOwner(owner);
614	        pet.getType().setName(null);
615	        this.clinicService.savePet(pet);
616	        PetDto petDto = petMapper.toPetDto(pet);
617	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
618	            .buildAndExpand(pet.getId()).toUri());
619	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
620	    }
621	
622	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
623	    @Override
624	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
625	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
626	        if (currentOwner != null) {
627	            Pet currentPet = this.clinicService.findPetById(petId);
628	            if (currentPet != null) {
629	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
630	                currentPet.setName(petFieldsDto.getName());
631	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
632	                this.clinicService.savePet(currentPet);
633	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
634	            }
635	        }
636	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
637	    }
638	
639	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
640	    @Override
641	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
642	        HttpHeaders headers = new HttpHeaders();
643	        Visit visit = visitMapper.toVisit(visitFieldsDto);
644	        Pet pet = new Pet();
645	        pet.setId(petId);
646	        visit.setPet(pet);
647	        this.clinicService.saveVisit(visit);
648	        VisitDto visitDto = visitMapper.toVisitDto(visit);
649	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
650	            .buildAndExpand(visit.getId()).toUri());
651	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
652	    }
653	
654	
655	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
656	    @Override
657	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
658	        Owner owner = this.clinicService.findOwnerById(ownerId);
659	        if (owner != null) {
660	            Pet pet = owner.getPet(petId);
661	            if (pet != null) {
662	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
663	            }
664	        }
665	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
666	    }
667	}
